package ru.neverland.townyspecialization.production;

import java.nio.file.*;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import org.bukkit.configuration.file.YamlConfiguration;
import static ru.neverland.townyspecialization.production.ProductionRepository.*;

public final class ProfileGoodsSmoke {
    static int checks;static final UUID A=UUID.randomUUID(),B=UUID.randomUUID(),M=UUID.randomUUID(),N=UUID.randomUUID(),W=UUID.randomUUID();
    interface Work{void run()throws Exception;}
    static void check(boolean yes,String why){checks++;if(!yes)throw new AssertionError(why);}
    static void rejects(Work work,String why)throws Exception{try{work.run();}catch(IllegalArgumentException|ExecutionException expected){checks++;return;}throw new AssertionError(why);}
    static <T>T done(CompletionStage<T> stage)throws Exception{return stage.toCompletableFuture().get(10,TimeUnit.SECONDS);}
    static Stock stock(ProductionRepository r,UUID town,String product)throws Exception{return done(r.stock(town)).stream().filter(s->s.product().equals(product)).findFirst().orElse(new Stock(product,"","",0,0,0));}
    static ProfileGoodsBook.Terms quote(ProductionRepository r,UUID other,Map<String,Long> give,Map<String,Long> receive)throws Exception{return done(r.goodsQuote(UUID.randomUUID(),A,other,W,"world:CUSTOM:1:WINTER","Точная смета",give,receive,M,"MayorA",System.currentTimeMillis()+60_000));}
    static void sql(Path file,String sql)throws Exception{try(var c=DriverManager.getConnection("jdbc:sqlite:"+file);var s=c.createStatement()){s.execute(sql);}}
    public static void main(String[] args)throws Exception{
        var y=new YamlConfiguration();try(var in=ProfileGoodsSmoke.class.getResourceAsStream("/production.yml")){y.load(new java.io.InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8));}var catalog=ProductionCatalog.load(y);var limits=catalog.limits();var farm=catalog.products().get("farm_provisions");var port=catalog.products().get("port_equipment");
        Path file=Files.createTempDirectory("profile-barter-").resolve("production.sqlite");var repo=new ProductionRepository(file);done(repo.ready());ProductionSmoke.produce(repo,A,farm,8,limits);ProductionSmoke.produce(repo,B,port,8,limits);
        var terms=quote(repo,B,Map.of(farm.id(),2L),Map.of(port.id(),1L));check(stock(repo,A,farm.id()).available()==8&&done(repo.goodsEntries(A,1)).isEmpty(),"quotation alone creates no reserve or goods");check(ProfileGoodsBook.decode(ProfileGoodsBook.encode(terms)).equals(terms),"exact parties quantities labels period actor and hash round trip");
        var changed=new HashMap<String,Object>(terms.view());changed.put("give",Map.of(farm.id(),1L));rejects(()->ProfileGoodsBook.read(changed),"changed quote cannot keep original confirmation hash");
        ProfileGoodsBook.Entry held;try(var lock=DriverManager.getConnection("jdbc:sqlite:"+file);var statement=lock.createStatement()){statement.execute("BEGIN IMMEDIATE");var acknowledgement=repo.goodsConfirm(terms,limits);check(!acknowledgement.toCompletableFuture().isDone(),"physical SQLite writer delay leaves the first confirmation pending");try(var r=statement.executeQuery("SELECT available,reserved FROM stock WHERE town='"+A+"' AND product='farm_provisions'")){check(r.next()&&r.getLong(1)==8&&r.getLong(2)==0,"unacknowledged reserve is absent from the committed stock snapshot");}check(ru.neverland.core.SuiteState.tryRun("profile goods delayed SQLite",()->{}),"SQLite wait does not hold the suite guard");statement.execute("COMMIT");held=done(acknowledgement);}var cache=new ProfileGoodsCache();cache.publish(new GoodsSnapshot(2,List.of(held)));cache.publish(new GoodsSnapshot(1,List.of()));check(cache.active().size()==1,"late empty boot snapshot cannot hide newer committed reserve");cache.publish(new GoodsSnapshot(3,List.of()));cache.publish(new GoodsSnapshot(2,List.of(held)));check(cache.active().isEmpty(),"late held snapshot cannot revive already acknowledged cancellation");check(held.state().equals("HELD")&&stock(repo,A,farm.id()).available()==6&&stock(repo,A,farm.id()).reserved()==2,"first mayor ACK reserves exact available source goods");done(repo.goodsConfirm(terms,limits));check(stock(repo,A,farm.id()).reserved()==2,"duplicate first confirmation never double reserves");
        var joint=done(repo.createProject(UUID.randomUUID(),A,catalog.projects().get("common_supply"),catalog.products(),"MayorA",limits));done(repo.contribute(UUID.randomUUID(),joint.project().id(),A,"agricultural",farm.id(),2,"MayorA"));final var current=repo;
        rejects(()->quote(current,B,Map.of(farm.id(),5L),Map.of(port.id(),1L)),"joint project and fair reserves cannot be sold a second time");rejects(()->done(current.goodsAccept(terms.id(),UUID.randomUUID(),A,M,"MayorA",terms.hash(),limits)),"sender cannot act as the other city");rejects(()->done(current.goodsAccept(terms.id(),UUID.randomUUID(),B,N,"MayorB","wrong hash",limits)),"other mayor must confirm exact stored terms");
        UUID receipt=UUID.randomUUID();var swapped=done(repo.goodsAccept(terms.id(),receipt,B,N,"MayorB",terms.hash(),limits));check(swapped.state().equals("SWAPPED")&&receipt.equals(swapped.receipt()),"both towns and unique receipt commit together");
        check(stock(repo,A,farm.id()).available()==4&&stock(repo,A,farm.id()).reserved()==2&&stock(repo,A,farm.id()).produced()==8&&stock(repo,A,farm.id()).sent()==2,"swap leaves unrelated joint reserve untouched and preserves actual production");
        check(stock(repo,B,farm.id()).available()==2&&stock(repo,B,farm.id()).produced()==0&&stock(repo,B,farm.id()).received()==2,"incoming goods have received counter rather than invented local production");check(stock(repo,A,port.id()).available()==1&&stock(repo,A,port.id()).received()==1&&stock(repo,B,port.id()).available()==7&&stock(repo,B,port.id()).sent()==1,"opposite side settles exact agreed amount");
        done(repo.goodsAccept(terms.id(),receipt,B,N,"MayorB",terms.hash(),limits));done(repo.goodsAccept(terms.id(),UUID.randomUUID(),B,N,"MayorB",terms.hash(),limits));check(stock(repo,B,farm.id()).available()==2,"same offer cannot transfer again even with a new client receipt");
        rejects(()->done(current.goodsCancel(terms.id(),A,M,"MayorA","Cannot reverse an accepted trade",false)),"accepted trade cannot fabricate a refund");done(repo.finishProject(joint.project().id(),A,true,"MayorA","Joint project neutrally cancelled"));check(stock(repo,A,farm.id()).available()==6&&stock(repo,A,farm.id()).reserved()==0,"old joint cancellation returns only its own original reserve after barter");
        var preparation=quote(repo,null,Map.of(port.id(),1L),Map.of());done(repo.goodsConfirm(preparation,limits));check(stock(repo,A,port.id()).reserved()==1&&stock(repo,A,port.id()).available()==0,"real received goods can form a separate seasonal reserve");
        var second=quote(repo,B,Map.of(farm.id(),1L),Map.of(port.id(),2L));done(repo.goodsConfirm(second,limits));rejects(()->done(current.goodsAccept(second.id(),receipt,B,N,"MayorB",second.hash(),limits)),"receipt from another offer cannot settle a new one");
        done(repo.goodsExpire(Map.of(W.toString(),"world:CUSTOM:2:SPRING")));check(done(repo.goodsEntry(second.id())).state().equals("EXPIRED")&&stock(repo,A,farm.id()).available()==6,"calendar rollover returns exact source offer escrow without penalty");check(done(repo.goodsEntry(preparation.id())).state().equals("HELD"),"seasonal preparation keeps its separately confirmed storage deadline");
        rejects(()->done(current.goodsCancel(preparation.id(),B,N,"MayorB","Foreign city cannot release reserve",false)),"another mayor cannot release owned stock");done(repo.goodsCancel(preparation.id(),A,M,"MayorA","Seasonal reserve released by mayor",false));done(repo.goodsCancel(preparation.id(),A,M,"MayorA","Seasonal reserve released by mayor",false));check(stock(repo,A,port.id()).available()==1&&stock(repo,A,port.id()).reserved()==0&&stock(repo,A,port.id()).received()==1,"repeated release returns reserve once without erasing receipt counters");
        var promised=done(repo.createBatch(UUID.randomUUID(),B,port,2,"MayorB",limits));var capacity=quote(repo,B,Map.of(farm.id(),2L),Map.of(port.id(),1L));done(repo.goodsConfirm(capacity,limits));var narrow=new ProductionCatalog.Limits(3,200,8,10,20000,3,100);rejects(()->done(current.goodsAccept(capacity.id(),UUID.randomUUID(),B,N,"MayorB",capacity.hash(),narrow)),"incoming capacity accounts already promised unfinished production");check(done(repo.goodsEntry(capacity.id())).state().equals("HELD")&&stock(repo,A,farm.id()).reserved()==2,"capacity refusal changes neither escrow nor recipient");done(repo.goodsCancel(capacity.id(),A,M,"MayorA","Cancel after capacity refusal",false));done(repo.acknowledge(promised.id(),ProductionSmoke.source(promised,"CANCELLED"),"MayorB"));
        var pending=quote(repo,B,Map.of(farm.id(),2L),Map.of(port.id(),1L));done(repo.goodsConfirm(pending,limits));done(repo.closeAsync());repo=new ProductionRepository(file);done(repo.ready());check(done(repo.goodsEntry(pending.id())).terms().equals(pending)&&stock(repo,A,farm.id()).reserved()==2,"restart restores pending exact offer and reserve without automatically trading");
        sql(file,"CREATE TRIGGER fail_swap BEFORE UPDATE OF state ON seasonal_entries WHEN NEW.state='SWAPPED' BEGIN SELECT RAISE(ABORT,'fixture swap fault'); END");final var fault=repo;rejects(()->done(fault.goodsAccept(pending.id(),UUID.randomUUID(),B,N,"MayorB",pending.hash(),limits)),"real SQL failure after both stock movements rolls transaction back");check(!repo.available(),"uncertain storage error closes optional goods writes");done(repo.closeAsync());sql(file,"DROP TRIGGER fail_swap");repo=new ProductionRepository(file);done(repo.ready());check(done(repo.goodsEntry(pending.id())).state().equals("HELD")&&stock(repo,A,farm.id()).available()==4&&stock(repo,A,farm.id()).reserved()==2&&stock(repo,B,farm.id()).available()==2,"reopen proves no partial swap no free goods and no false receipt");done(repo.goodsCancel(pending.id(),A,M,"MayorA","Cancelled after verified rollback",false));
        check(done(repo.goodsEntries(A,1)).size()==5&&done(repo.history(B,1)).stream().anyMatch(h->h.get("kind").equals("season-swap")),"durable status lists and both-city history survive restart");var audits=done(repo.auditPending());var directions=audits.stream().filter(r->r.kind().equals("CITY_SEASON_FAIR")&&r.outcome().equals("SWAPPED")).toList();check(directions.size()==2&&directions.stream().map(r->r.from().id()).collect(java.util.stream.Collectors.toSet()).equals(Set.of(A.toString(),B.toString()))&&directions.stream().mapToLong(ru.neverland.core.AuditRecord::quantity).sum()==3,"durable swap audit has exact directions and party quantities, no money value");check(directions.stream().allMatch(r->r.actor().id().equals(N.toString())&&r.actor().town().equals(B.toString())&&r.money().isEmpty()),"swap audit freezes final mayor actual city in both directions and does not invent currency");var created=audits.stream().filter(r->r.outcome().equals("HELD")&&r.operation().equals(terms.id().toString())).findFirst().orElseThrow();check(created.actor().id().equals(M.toString()),"unflushed reserve audit keeps first mayor after later swap");check(repo.available(),"seasonal audit construction cannot fault production ledger");done(repo.closeAsync());migration();
        System.out.println("ProfileGoodsSmoke PASS: "+checks+" assertions; backed stock, exact two-mayor terms, reservations, migration, capacities, conservation, rollback and recovery");
    }
    static void migration()throws Exception{
        Path file=Files.createTempDirectory("profile-schema-one-").resolve("production.sqlite");Class.forName("org.sqlite.JDBC");
        try(var c=DriverManager.getConnection("jdbc:sqlite:"+file);var s=c.createStatement()){
            s.execute("CREATE TABLE products(id TEXT PRIMARY KEY,profile TEXT NOT NULL,title TEXT NOT NULL)");s.execute("INSERT INTO products VALUES('farm_provisions','agricultural','Food')");s.execute("INSERT INTO products VALUES('port_equipment','port','Port')");
            s.execute("CREATE TABLE stock(town TEXT NOT NULL,product TEXT NOT NULL,available INTEGER NOT NULL CHECK(available>=0),reserved INTEGER NOT NULL CHECK(reserved>=0),produced INTEGER NOT NULL CHECK(produced>=available+reserved),PRIMARY KEY(town,product))");
            s.execute("INSERT INTO stock VALUES('"+A+"','farm_provisions',2,1,5)");s.execute("INSERT INTO stock VALUES('"+A+"','port_equipment',0,0,7)");s.execute("PRAGMA user_version=1");
        }
        var repo=new ProductionRepository(file);done(repo.ready());var food=stock(repo,A,"farm_provisions");var consumed=stock(repo,A,"port_equipment");check(food.available()==2&&food.reserved()==1&&food.produced()==5&&food.received()==0&&food.sent()==0,"schema1 migration preserves existing reserves and production with zero exchange counters");check(consumed.available()==0&&consumed.reserved()==0&&consumed.produced()==7,"schema1 migration preserves historically consumed zero-stock rows");done(repo.closeAsync());repo=new ProductionRepository(file);done(repo.ready());check(stock(repo,A,"farm_provisions").equals(food)&&stock(repo,A,"port_equipment").equals(consumed),"schema2 migration is idempotent across complete reopen");done(repo.closeAsync());
    }
}
